const axios = require('axios');

const subdomain = 'avaya1234';
const bearerToken = 'your-access-token-here';

async function startWorkflow() {
  try {
    const response = await axios.post(
      `https://core.${subdomain}.ec.avayacloud.com/api/workflow/v1/workflows/sessions`,
      {
        workflowId: 'wf_customer_inquiry',
        workflowVersionId: 'v2.1',
        variables: {
          customer_name: 'John Smith',
          order_id: 'ORD-2024-1984',
          issue_type: 'billing'
        }
      },
      {
        headers: {
          'Authorization': `Bearer ${bearerToken}`,
          'Content-Type': 'application/json'
        }
      }
    );

    console.log('Session ID:', response.data.sessionId);
    console.log('Status:', response.data.status);
  } catch (error) {
    console.error('Error:', error.response?.data || error.message);
  }
}

startWorkflow();

import requests

subdomain = 'avaya1234'
bearer_token = 'your-access-token-here'

url = f'https://core.{subdomain}.ec.avayacloud.com/api/workflow/v1/workflows/sessions'

headers = {
    'Authorization': f'Bearer {bearer_token}',
    'Content-Type': 'application/json'
}

payload = {
    'workflowId': 'wf_customer_inquiry',
    'workflowVersionId': 'v2.1',
    'variables': {
        'customer_name': 'John Smith',
        'order_id': 'ORD-2024-1984',
        'issue_type': 'billing'
    }
}

response = requests.post(url, json=payload, headers=headers)

if response.status_code == 200:
    data = response.json()
    print(f"Session ID: {data['sessionId']}")
    print(f"Status: {data['status']}")
else:
    print(f"Error: {response.status_code} - {response.text}")

